 sources.append(dict(id=rid,cache_key=k,url=u,publisher=pub,title=title,read_at=NOW,section=section,passage=passage,passage_format='paraphrase',population=pop,limits=limits,reading_scope='selected_sections_actually_read',sha256=hashlib.sha256((CACHE/(k+'.raw')).read_bytes()).hexdigest()))
