findings=[('TB-PCR','MAJEUR','Ancien texte PCR prometteuse à valider : remplacer par recommandation EAU actuelle complémentaire.'),('TB-CULTURE','MAJEUR','80–90% ne doit plus être performance universelle ; exposer divergences avec EAU23,3–30%.'),('FANCONI','MAJEUR','La négation absolue de bénéfice précoce cystéamine sur Fanconi contredit recommandations2026.'),('PRODUITS','MAJEUR','Compléter contre-indications produit, horaire dosage Procysbi, surveillance Myambutol IR et divergence Pyrazinamide.'),('SEMIO','MAJEUR','Six sous-onglets dont9sections sémiologiques manquent.'),('FIGURES','MAJEUR','Figures anatomiques/histologiques SVG sans provenance humaine à remplacer par originaux vérifiés.'),('SCH-COHORT','MAJEUR','Proportions tests positifs confondues avec sensibilités ; corriger dénominateurs et biais.'),('CIM-PLACEMENT','editorial','Déplacer annexe codage après conclusion clinique.'),('SYPH-DIAG','MAJEUR','Syphilis tardive peut être latente sans manifestation tertiaire ; enrichir diagnostic sérologique et suivi.')]
